void Need(bool value,string message){if(!value)throw new Exception(message);}
void Pass(string name){checks.Add(name);Console.WriteLine("PASS "+name);}
void Reject(Action action){try{action();}catch(Exception e) when(e is InvalidDataException or InvalidOperationException or ArgumentException){rejected++;return;}throw new Exception("Invalid operation accepted.");}
async Task RejectAsync(Func<Task> action){try{await action();}catch(Exception e) when(e is IOException or InvalidDataException or InvalidOperationException or SocketException or OperationCanceledException){rejected++;return;}throw new Exception("Invalid async operation accepted.");}
async Task Until(Func<bool> condition,int milliseconds=5000){var watch=Stopwatch.StartNew();while(!condition()){if(watch.ElapsedMilliseconds>milliseconds)throw new TimeoutException("Timed out waiting for cooperative state.");await Task.Delay(15);}}
