void Ready(CoopSession session){session.SetReady(0,true,session.Identity);session.SetReady(1,true,session.Identity);Need(session.StartGame(),"Session did not start.");}
byte[] Packet(string kind,object body,int protocol=1)=>JsonSerializer.SerializeToUtf8Bytes(new{ProtocolVersion=protocol,Kind=kind,Body=body},CoopJson.Options);
async Task WritePacket(NetworkStream stream,byte[] data,bool fragmented=false){byte[] header=new byte[4];BinaryPrimitives.WriteInt32BigEndian(header,data.Length);if(fragmented){foreach(byte b in header)await stream.WriteAsync(new byte[]{b});await stream.WriteAsync(data.AsMemory(0,data.Length/2));await stream.WriteAsync(data.AsMemory(data.Length/2));}else{await stream.WriteAsync(header);await stream.WriteAsync(data);}}
async Task<JsonDocument> ReadPacket(NetworkStream stream){using var cts=new CancellationTokenSource(4000);byte[] header=new byte[4];await stream.ReadExactlyAsync(header,cts.Token);int length=BinaryPrimitives.ReadInt32BigEndian(header);Need(length is >0 and <=65536,"Received unbounded server frame.");byte[] body=new byte[length];await stream.ReadExactlyAsync(body,cts.Token);return JsonDocument.Parse(body);}
